
const WORDS=[{"id": 0, "w": "上任", "p": "shàngrèn", "t": "动词", "m": "nhậm chức", "coll": "正式上任、新官上任", "s": "新经理刚刚上任，就主动了解各部门的工作情况。"}, {"id": 1, "w": "职位", "p": "zhíwèi", "t": "名词", "m": "chức vụ", "coll": "申请职位、担任职位", "s": "她申请了一个与自己专业相关的职位，希望积累实际经验。"}, {"id": 2, "w": "资深", "p": "zīshēn", "t": "形容词", "m": "thâm niên, lâu năm", "coll": "资深教师、资深员工", "s": "这位资深员工不仅经验丰富，也很愿意帮助刚入职的同事。"}, {"id": 3, "w": "创立", "p": "chuànglì", "t": "动词", "m": "sáng lập, thành lập", "coll": "创立公司、创立品牌", "s": "几位年轻人共同创立了一家小公司，专门开发学习软件。"}, {"id": 4, "w": "沏", "p": "qī", "t": "动词", "m": "pha (trà, cà phê...)", "coll": "沏茶、沏一壶茶", "s": "客人到访时，他先沏了一壶茶，再请大家坐下慢慢聊。"}, {"id": 5, "w": "风气", "p": "fēngqì", "t": "名词", "m": "bầu không khí, nếp sống", "coll": "良好风气、社会风气", "s": "互相尊重、乐于合作的风气，能让新人更快地融入团队。"}, {"id": 6, "w": "唯独", "p": "wéidú", "t": "副词", "m": "chỉ có, duy nhất", "coll": "唯独他不知道、唯独缺少经验", "s": "大家都收到了通知，唯独他因为手机没电，没有及时看到消息。"}, {"id": 7, "w": "搭档", "p": "dādàng", "t": "名词", "m": "cộng sự, người cộng tác", "coll": "工作搭档、合作搭档", "s": "两位搭档分工明确，配合得十分默契。"}, {"id": 8, "w": "就职", "p": "jiùzhí", "t": "动词", "m": "nhận chức/nhận việc", "coll": "正式就职、就职于公司", "s": "毕业以后，她就职于一家教育研究机构。"}, {"id": 9, "w": "边缘", "p": "biānyuán", "t": "名词", "m": "rìa, vùng ven", "coll": "城市边缘、处于边缘", "s": "这家工厂位于城市边缘，离市中心有一段距离。"}, {"id": 10, "w": "眼色", "p": "yǎnsè", "t": "名词", "m": "cái nháy mắt (để ra hiệu), cái liếc mắt đầy ngụ ý", "coll": "使眼色、看眼色", "s": "同事悄悄向他使了个眼色，提醒他先听完对方的话。"}, {"id": 11, "w": "指标", "p": "zhǐbiāo", "t": "名词", "m": "chỉ tiêu", "coll": "完成指标、考核指标", "s": "制定考核指标时，应该充分考虑工作的实际情况。"}, {"id": 12, "w": "成天", "p": "chéngtiān", "t": "副词", "m": "suốt ngày", "coll": "成天忙碌、成天抱怨", "s": "与其成天抱怨，不如认真想想自己能作出哪些改变。"}, {"id": 13, "w": "吹牛", "p": "chuīniú", "t": "动词", "m": "ba hoa, khoác lác", "coll": "爱吹牛、别吹牛", "s": "他从不爱吹牛，总是用实际行动证明自己的能力。"}, {"id": 14, "w": "溜", "p": "liū", "t": "动词", "m": "chuồn mất", "coll": "偷偷溜走、溜出房间", "s": "会议还没结束，他就想偷偷溜走，被同事及时叫住了。"}, {"id": 15, "w": "等级", "p": "děngjí", "t": "名词", "m": "đẳng cấp, cấp bậc", "coll": "质量等级、划分等级", "s": "这些产品按照质量等级分别包装，便于顾客选择。"}, {"id": 16, "w": "公道", "p": "gōngdao", "t": "形容词", "m": "công bằng, hợp lý", "coll": "办事公道、价格公道", "s": "这位主管办事公道，遇到争议时总会认真听取双方的意见。"}, {"id": 17, "w": "哼", "p": "hng", "t": "叹词", "m": "hừ, hừm (biểu thị sự bực bội hoặc không tin)", "coll": "哼了一声、哼，别吹牛了", "s": "“哼，别以为我不知道！”她说完，转过身去，不再理他。"}, {"id": 18, "w": "不像话", "p": "bùxiànghuà", "t": "形容词", "m": "vô lý, kỳ cục", "coll": "太不像话、实在不像话", "s": "未经允许就擅自修改别人的材料，实在太不像话了。"}, {"id": 19, "w": "明明", "p": "míngmíng", "t": "副词", "m": "rõ ràng", "coll": "明明知道、明明已经完成", "s": "他明明知道会议已经改期，却忘了通知其他同事。"}, {"id": 20, "w": "欺负", "p": "qīfu", "t": "动词", "m": "ăn hiếp, bắt nạt", "coll": "欺负新人、受到欺负", "s": "无论在学校还是职场，都不应该以资历为借口欺负别人。"}, {"id": 21, "w": "大不了", "p": "dàbùliǎo", "t": "副词", "m": "cùng lắm, trong trường hợp xấu nhất", "coll": "大不了重来、大不了再试一次", "s": "这次尝试即使没有成功，大不了重新调整方法再来。"}, {"id": 22, "w": "展示", "p": "zhǎnshì", "t": "动词", "m": "thể hiện", "coll": "展示成果、展示才华", "s": "这次交流会为年轻教师提供了展示研究成果的机会。"}, {"id": 23, "w": "才干", "p": "cáigàn", "t": "名词", "m": "tài năng, năng lực", "coll": "发挥才干、管理才干", "s": "公司愿意给新人机会，让他们充分发挥自己的才干。"}, {"id": 24, "w": "计较", "p": "jìjiào", "t": "动词", "m": "tính toán, so đo", "coll": "斤斤计较、不必计较", "s": "同事之间不必为一点小事过分计较，应把精力放在解决问题上。"}, {"id": 25, "w": "全力以赴", "p": "quánlì yǐfù", "t": "成语", "m": "dốc toàn lực, không tiếc công sức", "coll": "全力以赴地工作、为目标全力以赴", "s": "为了按时完成任务，团队成员全力以赴，每天都认真核对进度。"}, {"id": 26, "w": "怠慢", "p": "dàimàn", "t": "动词", "m": "lạnh nhạt, thờ ơ", "coll": "怠慢客人、不敢怠慢", "s": "得知客户有重要问题，他不敢怠慢，立即安排了沟通时间。"}, {"id": 27, "w": "敷衍", "p": "fūyǎn", "t": "动词", "m": "làm lấy lệ, làm qua loa, hời hợt", "coll": "敷衍了事、敷衍别人", "s": "对待学生的提问，老师不能敷衍了事。"}, {"id": 28, "w": "想方设法", "p": "xiǎngfāng shèfǎ", "t": "成语", "m": "tìm đủ mọi cách", "coll": "想方设法解决、想方设法帮助", "s": "面对暂时的困难，大家想方设法，终于找到了解决办法。"}, {"id": 29, "w": "凑合", "p": "còuhe", "t": "动词", "m": "tạm chấp nhận, dùng tạm; làm tạm", "coll": "凑合着用、不能凑合", "s": "这台旧电脑虽然有点慢，暂时还可以凑合着用。"}, {"id": 30, "w": "忙碌", "p": "mánglù", "t": "形容词", "m": "bận rộn", "coll": "工作忙碌、忙碌的一天", "s": "尽管工作忙碌，她仍然坚持每周参加一次读书会。"}, {"id": 31, "w": "时光", "p": "shíguāng", "t": "名词", "m": "thời gian", "coll": "珍惜时光、美好时光", "s": "回想起刚入职时的时光，他仍然十分感谢那些帮助过自己的人。"}, {"id": 32, "w": "飞跃", "p": "fēiyuè", "t": "动词", "m": "vượt bậc, nhảy vọt", "coll": "实现飞跃、质的飞跃", "s": "经过系统培训，他的专业能力实现了质的飞跃。"}, {"id": 33, "w": "投诉", "p": "tóusù", "t": "动词", "m": "khiếu nại", "coll": "向平台投诉、处理投诉", "s": "发现商品有质量问题后，顾客通过平台提出了投诉。"}, {"id": 34, "w": "激情", "p": "jīqíng", "t": "名词", "m": "tình cảm mãnh liệt, cảm xúc mạnh mẽ", "coll": "充满激情、工作激情", "s": "这位老师始终对教学充满激情，经常尝试新的课堂活动。"}, {"id": 35, "w": "年度", "p": "niándù", "t": "名词", "m": "năm, niên độ (công tác, tài chính…)", "coll": "本年度、年度报告", "s": "本年度的工作计划已经确定，各部门将按要求逐步落实。"}, {"id": 36, "w": "考核", "p": "kǎohé", "t": "动词", "m": "kiểm tra, đánh giá", "coll": "定期考核、考核结果", "s": "单位每半年考核一次员工的业务能力。"}, {"id": 37, "w": "敬业", "p": "jìngyè", "t": "动词", "m": "yêu nghề, cống hiến cho công việc", "coll": "爱岗敬业、敬业精神", "s": "她的敬业精神体现在对每一项任务都认真负责。"}, {"id": 38, "w": "兢兢业业", "p": "jīngjīng yèyè", "t": "成语", "m": "tận tâm, cẩn trọng và cần mẫn", "coll": "兢兢业业地工作、工作兢兢业业", "s": "他在这个岗位上兢兢业业地工作了多年，赢得了同事们的尊重。"}, {"id": 39, "w": "回报", "p": "huíbào", "t": "动词", "m": "đền đáp", "coll": "回报信任、得到回报", "s": "她希望用出色的工作回报老师和同事们的信任。"}, {"id": 40, "w": "当初", "p": "dāngchū", "t": "名词", "m": "lúc đầu, trước đây", "coll": "当初的决定、回想当初", "s": "回想当初，他并没有想到自己会一直从事这份工作。"}, {"id": 41, "w": "技巧", "p": "jìqiǎo", "t": "名词", "m": "kỹ năng, kỹ xảo", "coll": "沟通技巧、掌握技巧", "s": "掌握有效的沟通技巧，有助于减少误会，提高合作效率。"}, {"id": 42, "w": "传授", "p": "chuánshòu", "t": "动词", "m": "truyền dạy, truyền đạt", "coll": "传授经验、传授知识", "s": "师傅耐心地向年轻员工传授操作经验。"}, {"id": 43, "w": "人格", "p": "réngé", "t": "名词", "m": "nhân cách, tính cách", "coll": "尊重人格、独立人格", "s": "批评一个人的工作不等于可以否定他的人格。"}, {"id": 44, "w": "施展", "p": "shīzhǎn", "t": "动词", "m": "phát huy, thi thố", "coll": "施展才华、施展本领", "s": "新的项目给了她施展才华的空间，也带来了更大的挑战。"}, {"id": 45, "w": "时机", "p": "shíjī", "t": "名词", "m": "cơ hội, thời cơ", "coll": "把握时机、合适的时机", "s": "提出建议时，既要注意表达方式，也要选择合适的时机。"}];
